/* ---- analytics charts */
function lineChart(rnd, w, h, sw = 2) {
  const a = series(rnd, 26, 60, 9).map((v, i) => v + i * 1.4), b = series(rnd, 26, 52, 7).map((v, i) => v + i * 0.6);
  const max = Math.max(...a, ...b) * 1.1, step = w / 25;
  const path = (d) => d.map((v, i) => (i ? "L" : "M") + (i * step).toFixed(1) + " " + (h - (v / max) * h).toFixed(1)).join(" ");
  const grid = [0, 0.25, 0.5, 0.75].map((g) => `<line x1="0" x2="${w}" y1="${h * g + 0.5}" y2="${h * g + 0.5}" stroke="var(--border)" stroke-dasharray="3 4" vector-effect="non-scaling-stroke"/>`).join("");
  const la = path(a), mx = 18 * step, my = h - (a[18] / max) * h;
  return `<svg viewBox="0 0 ${w} ${h}" width="100%" height="${h}" preserveAspectRatio="none" style="display:block;overflow:visible">${grid}<path d="${la} L${w} ${h} L0 ${h}Z" fill="color-mix(in oklab,var(--primary) 12%,transparent)"/><path d="${path(b)}" fill="none" stroke="var(--accent)" stroke-width="${sw}" stroke-dasharray="5 4" vector-effect="non-scaling-stroke"/><path d="${la}" fill="none" stroke="var(--primary)" stroke-width="${sw}" vector-effect="non-scaling-stroke"/><line x1="${mx}" x2="${mx}" y1="0" y2="${h}" stroke="var(--text)" stroke-opacity=".35" vector-effect="non-scaling-stroke"/></svg>`;
}
function donut(segs, size, sw) {
  const r = (size - sw) / 2, C = 2 * Math.PI * r; let acc = 0;
  return `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" style="transform:rotate(-90deg);flex:none">${segs.map((v, i) => { const len = (v / 100) * C, s = `<circle cx="${size / 2}" cy="${size / 2}" r="${r}" fill="none" stroke="${SEG[i]}" stroke-width="${sw}" stroke-dasharray="${(len - 2).toFixed(1)} ${(C - len + 2).toFixed(1)}" stroke-dashoffset="${(-acc).toFixed(1)}"/>`; acc += len; return s; }).join("")}</svg>`;
}
