function cohortGrid(rnd, rows, cols, cell, fs) {
  const names = ["Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct"].slice(-rows), sizes = [412, 388, 451, 497, 463, 529, 574].slice(-rows);
  let out = `<div style="display:grid;grid-template-columns:${fs > 11 ? 74 : 46}px repeat(${cols},minmax(0,1fr));gap:3px;font-size:${fs}px">`;
  out += `<div class="muted" style="font-weight:600">Cohort</div>` + Array.from({ length: cols }, (_, j) => `<div class="muted" style="font-weight:600;text-align:center">M${j}</div>`).join("");
  names.forEach((n, i) => {
    out += `<div style="display:flex;flex-direction:column;justify-content:center;line-height:1.2"><span style="font-weight:600;white-space:nowrap">${n} ’26</span>${fs > 11 ? `<span class="muted" style="font-size:11px">${sizes[i]}</span>` : ""}</div>`;
    let v = 100;
    for (let j = 0; j < cols; j++) {
      if (j > 0) v -= j === 1 ? 7 + rnd() * 5 : 2 + rnd() * 4;
      if (j > rows - 1 - i) { out += `<div style="height:${cell}px;border-radius:var(--radius-sm);background:color-mix(in oklab,var(--border) 35%,transparent)"></div>`; continue; }
      const mix = Math.round(14 + ((v - 55) / 45) * 78);
      out += `<div class="num" style="height:${cell}px;border-radius:var(--radius-sm);display:grid;place-items:center;font-size:${fs}px;font-weight:600;background:color-mix(in oklab,var(--primary) ${mix}%,var(--surface));color:${mix > 52 ? "var(--on-primary)" : "var(--text)"}">${Math.round(v)}%</div>`;
    }
  });
  return out + "</div>";
}
