/* ======================================================================= HEALTH (Steadyfit) */
const RINGS = [["Move", 70, "420", "/ 600 kcal", "var(--primary)"], ["Exercise", 80, "24", "/ 30 min", "var(--accent)"], ["Habits", 67, "4", "/ 6 done", "color-mix(in oklab,var(--primary) 45%,var(--text))"]];
function rings(size, sw) {
  return `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" style="transform:rotate(-90deg);flex:none">${RINGS.map(([, pct, , , c], i) => { const r = size / 2 - sw / 2 - i * (sw + 4), C = 2 * Math.PI * r; return `<circle cx="${size / 2}" cy="${size / 2}" r="${r}" fill="none" stroke="${c}" stroke-opacity=".16" stroke-width="${sw}"/><circle cx="${size / 2}" cy="${size / 2}" r="${r}" fill="none" stroke="${c}" stroke-width="${sw}" stroke-linecap="round" stroke-dasharray="${((pct / 100) * C).toFixed(1)} ${C.toFixed(1)}"/>`; }).join("")}</svg>`;
}
const HABITS = [["apps_drop", "Drink 2 L of water", "8 of 8 glasses", true, "12 days"], ["apps_leaf", "10-minute stretch", "Done at 7:15", true, "18 days"], ["doc", "Read 20 pages", "Done at 8:02", true, "6 days"], ["spark", "5 minutes of breathing", "Done at 8:30", true, "9 days"], ["apps_walk", "Walk 8,000 steps", "5,412 so far", false, "4 days", 68], ["apps_moon", "No screens after 22:30", "Tonight", false, "2 days"]];
const WEEK = [["M", 42], ["T", 30], ["W", 55], ["T", 0], ["F", 38], ["S", 61], ["S", 24]];
const habitRow = ([i, t, d, done, streak, prog], compact) => `<div style="display:flex;align-items:center;gap:12px;padding:${compact ? "7px 0" : "10px 0"};border-top:1px solid var(--border)"><span style="width:${compact ? 32 : 36}px;height:${compact ? 32 : 36}px;border-radius:var(--radius);display:grid;place-items:center;flex:none;background:color-mix(in oklab,var(--primary) 10%,var(--surface));color:var(--primary)">${ic(i, compact ? 16 : 18)}</span><div style="flex:1;min-width:0;line-height:1.3"><div style="font-weight:600;font-size:13px;${done ? "text-decoration:line-through;text-decoration-color:color-mix(in oklab,var(--text) 40%,transparent)" : ""}">${t}</div>${prog ? `<div style="display:flex;align-items:center;gap:8px;margin-top:3px"><div style="flex:1;max-width:140px;height:5px;border-radius:3px;background:color-mix(in oklab,var(--primary) 14%,var(--surface))"><div style="width:${prog}%;height:100%;border-radius:3px;background:var(--primary)"></div></div><span class="muted" style="font-size:12px">${d}</span></div>` : `<div class="muted" style="font-size:12px">${d}</div>`}</div>${compact ? "" : `<span class="muted" style="font-size:12px;display:flex;gap:4px;align-items:center">${ic("apps_flame", 14)}${streak}</span>`}${done ? `<span style="width:24px;height:24px;border-radius:50%;background:var(--primary);color:var(--on-primary);display:grid;place-items:center;flex:none">${ic("check", 14)}</span>` : `<span style="width:24px;height:24px;border-radius:50%;border:2px solid color-mix(in oklab,var(--text) 25%,var(--border));flex:none"></span>`}</div>`;
const weekBars = (h, labels = true) => `<div style="display:flex;align-items:flex-end;gap:8px;height:${h}px;position:relative"><span style="position:absolute;left:0;right:0;bottom:${(30 / 65) * h}px;border-top:1.5px dashed color-mix(in oklab,var(--text) 35%,transparent)"></span>${WEEK.map(([d, v], i) => `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:4px;height:100%;justify-content:flex-end"><div style="width:100%;height:${Math.max(4, (v / 65) * (h - (labels ? 18 : 0)))}px;border-radius:var(--radius-sm) var(--radius-sm) 2px 2px;background:${i === 6 ? "var(--accent)" : v >= 30 ? "var(--primary)" : "color-mix(in oklab,var(--primary) 30%,var(--surface))"}"></div>${labels ? `<span class="muted" style="font-size:11px;${i === 6 ? "color:var(--text);font-weight:700" : ""}">${d}</span>` : ""}</div>`).join("")}</div>`;
